<template>
  <div :class="cn('flex flex-col gap-1.5 relative w-full')">
    <p v-if="label" class="text-sm font-medium">{{ label }}</p>
    <Popover v-model:open="open">
      <PopoverAnchor class="relative">
        <PopoverTrigger as-child>
          <Button
            variant="outline"
            role="combobox"
            :aria-expanded="open"
            :class="cn('w-full h-10 justify-between', !modelValue && 'text-muted-foreground')"
          >
            <span class="flex min-w-0 flex-1 items-center overflow-hidden">
              <component :is="icon" v-if="icon" class="me-2 h-4 w-4 shrink-0" />
              <span v-if="selectedItem" class="min-w-0 truncate">
                {{ selectedItem.name ?? selectedItem.value }}
                <span v-if="selectedItem.subtitle" class="text-muted-foreground">
                  &middot; {{ selectedItem.subtitle }}
                </span>
                <!-- Inline rather than a second line: the trigger is a single-line, fixed-height button. -->
                <span v-if="selectedItem.caption" class="text-muted-foreground">
                  &middot; {{ selectedItem.caption }}
                </span>
              </span>
              <span v-else class="min-w-0 truncate">{{ placeholder }}</span>
            </span>
            <Spinner v-if="loading" class="ml-1 h-4 w-4 shrink-0" />
            <ChevronsUpDownIcon v-else-if="!clearable || !modelValue" class="h-4 w-4 shrink-0" />
            <span v-else class="h-4 w-4 shrink-0" />
          </Button>
        </PopoverTrigger>
        <XIcon
          v-if="clearable && !loading && modelValue"
          class="h-4 w-4 ml-2 shrink-0 absolute right-4 top-[0.75rem] cursor-pointer"
          @click.stop.prevent="onChange(null)"
        />
      </PopoverAnchor>
      <PopoverContent class="w-[var(--reka-popover-trigger-width)] p-0">
        <div v-if="props.items.length === 0" class="py-6 px-4 text-center text-sm">{{ emptyText }}</div>
        <Command v-else>
          <CommandInput v-if="props.items.length >= minItemsForSearch" :placeholder="inputPlaceholder" />
          <CommandList
            :class="
              cn(
                'relative z-0',
                props.items.length >= minItemsForSearch
                  ? 'max-h-[min(20rem,_calc(var(--reka-popover-content-available-height)-50px))]'
                  : 'max-h-[min(20rem,_calc(var(--reka-popover-content-available-height)-10px))]'
              )
            "
          >
            <CommandEmpty>{{ emptyText }}</CommandEmpty>
            <CommandGroup>
              <CommandItem
                v-for="(item, index) in props.items"
                :key="item.value ?? index"
                :value="item.value"
                class="cursor-pointer"
                @select="onChange(item.value)"
              >
                <CheckIcon
                  :class="cn('mr-2 h-4 w-4', modelValue && modelValue === item.value ? 'opacity-100' : 'opacity-0')"
                />
                <span class="flex min-w-0 flex-col">
                  <span class="truncate">
                    {{ item.name }}
                    <span v-if="item.subtitle" class="text-muted-foreground">&middot; {{ item.subtitle }}</span>
                  </span>
                  <span v-if="item.caption" class="truncate text-xs text-muted-foreground">{{ item.caption }}</span>
                </span>
              </CommandItem>
            </CommandGroup>
          </CommandList>
        </Command>
      </PopoverContent>
    </Popover>
  </div>
</template>

<script setup lang="ts" generic="T extends string">
import { CheckIcon, ChevronsUpDownIcon, XIcon } from 'lucide-vue-next';
import { cn } from '~/components/ui/utils';
import { Spinner } from '~/assets/icons';
import { type AcceptableValue, PopoverAnchor } from 'reka-ui';

interface Props {
  label?: string;
  items: SelectItem<T>[];
  placeholder?: string;
  inputPlaceholder?: string;
  emptyText?: string;
  loading?: boolean;
  minItemsForSearch?: number;
  icon?: any;
  clearable?: boolean;
}

const props = withDefaults(defineProps<Props>(), {
  placeholder: undefined,
  inputPlaceholder: undefined,
  emptyText: 'No items found.',
  label: undefined,
  loading: false,
  minItemsForSearch: 10,
  icon: undefined,
  clearable: true,
});

const modelValue = defineModel<T | null>({ default: null });

const open = ref(false);

const selectedItem = computed(() => {
  return props.items.find((item) => item.value === modelValue.value) ?? null;
});

function onChange(value: AcceptableValue) {
  const newValue = value as T | null;
  modelValue.value = newValue;
  open.value = false;
}
</script>
